/**
 * Files that change what every test does. A pull request touching one runs
 * the whole list: a new vitest, jsdom or setup file can blind any test.
 */
export const RUN_ALL_WHEN_CHANGED = [
  "package.json",
  "package-lock.json",
  "vitest.config.mts",
  "src/test-support/git-env.setup.ts",
];

const entryKey = (m) => JSON.stringify([m.id, m.test, m.file, m.find, m.replace, m.needs ?? null]);

/**
 * Which mutations a run checks (.github/workflows/mutations.yml).
 *
 * - `changed` (a pull request's files, relative to the repo root): only the
 *   mutations whose target or test file changed, plus any entry that is new
 *   or edited relative to `base` (the list at the PR's base). Everything else
 *   is left to the full run on main and the nightly one, which pass no
 *   `changed` and so check the whole list.
 * - `shard` ({index, total}, index from 1): every total-th mutation of what
 *   is left, so the shards of one run are disjoint and together are all of it.
 *
 * @template {{id: string, file: string, test: string, find: string, replace: string, needs?: string}} T
 * @param {T[]} all
 * @param {{changed?: string[] | null, base?: {id: string, file: string, test: string, find: string, replace: string, needs?: string}[] | null, shard?: {index: number, total: number} | null}} [options]
 * @returns {T[]}
 */
export function selectMutations(all, { changed = null, base = null, shard = null } = {}) {
  let picked = all;
  if (changed) {
    const files = new Set(changed);
    if (!RUN_ALL_WHEN_CHANGED.some((f) => files.has(f))) {
      const before = base ? new Set(base.map(entryKey)) : null;
      picked = all.filter(
        (m) => files.has(m.file) || files.has(m.test) || (before !== null && !before.has(entryKey(m))),
      );
    }
  }
  if (shard) picked = picked.filter((_, i) => i % shard.total === shard.index - 1);
  return picked;
}

/** "2/4" → {index: 2, total: 4}; anything else throws. */
export function parseShard(text) {
  const m = /^(\d+)\/(\d+)$/.exec(text ?? "");
  const index = m ? Number(m[1]) : NaN;
  const total = m ? Number(m[2]) : NaN;
  if (!(total >= 1 && index >= 1 && index <= total)) throw new Error(`--shard wants i/n with 1 <= i <= n, got ${text}`);
  return { index, total };
}

/**
 * The files a ref..HEAD diff touches, and the mutation list as it stood at `ref` ([] if absent).
 * @param {string} ref
 * @param {string} [root]
 * @returns {Promise<{changed: string[], base: {id: string, file: string, test: string, find: string, replace: string, needs?: string}[]}>}
 */
/**
 * A mutation's verdict from its test run. Exit 0 counts as GREEN (a survivor)
 * only when vitest printed its summary, i.e. tests ran and passed. Exit 0 with
 * no summary is NO-RUN, and still a failure: on 2026-09-29 a run went through
 * the very script under mutation (scripts/heavy.sh), the mutated script exited
 * 0 without starting vitest, and an unrun test was read as a pass.
 */
export function judgeRun(code, out) {
  if (code !== 0) return "red";
  // CI colours the summary ("Tests \x1b[22m \x1b[1m\x1b[32m21 passed"); on
  // 2026-10-13 a real survivor was reported as NO-RUN because of it.
  const plain = out.replace(/\x1b\[[0-9;]*m/g, "");
  return /Tests\s+\d+ passed/.test(plain) ? "GREEN" : "NO-RUN";
}

/**
 * How a mutation's test is started: through the box-wide `heavy` semaphore
 * when it is installed, directly where it is not (CI). Decided here, never by
 * calling scripts/heavy.sh, which is itself a mutation target: breaking it
 * would break the instrument measuring it.
 */
export function vitestCommand(testFile, hasHeavy) {
  const vitest = ["npx", "vitest", "run", testFile, "--reporter=dot", "--silent"];
  return hasHeavy ? ["heavy", ["--label", "high-desert mutation", "--", ...vitest]] : [vitest[0], vitest.slice(1)];
}

export async function changesSince(ref, root = ROOT) {
  const { stdout } = await execFileP("git", ["diff", "--name-only", ref, "HEAD"], { cwd: root });
  const changed = stdout.split("\n").filter(Boolean);
  let base = [];
  try {
    const { stdout: text } = await execFileP("git", ["show", `${ref}:scripts/mutate-check.mjs`], {
      cwd: root,
      maxBuffer: 64 * 1024 * 1024,
    });
    const tmp = path.join(await mkdtemp(path.join(tmpdir(), "mutate-base-")), "mutate-check.mjs");
    await writeFile(tmp, text, "utf8");
    // In a child process: a dynamic import() in this file is rewritten by vite
    // for every test that imports it, above the shebang, which breaks them.
    const { stdout: json } = await execFileP(
      process.execPath,
      ["--input-type=module", "-e", "const m = await import(process.argv[1]); console.log(JSON.stringify(m.MUTATIONS));", pathToFileURL(tmp).href],
      { maxBuffer: 64 * 1024 * 1024 },
    );
    base = JSON.parse(json) ?? [];
  } catch {
    base = []; // no list at the base: every entry is new
  }
  return { changed, base };
}

/**
 * Run only when invoked as a script. The list is also imported —
 * src/stores/__tests__/coverage.test.ts reads it to hold every store to at
 * least one mutation — and importing it must not start mutating files.
 */
const IS_MAIN = !!process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href;

if (IS_MAIN) {
  const args = process.argv.slice(2);
  const flag = (name) => {
    const i = args.indexOf(name);
    if (i === -1) return null;
    const v = args[i + 1];
    args.splice(i, 2);
    return v;
  };
  const changedFrom = flag("--changed-from");
  const shardArg = flag("--shard");
  const jsonOut = flag("--json");
  const startedAt = new Date().toISOString();
  const filters = args;
  const filtered = filters.length
    ? MUTATIONS.filter((m) => filters.some((f) => m.id.includes(f) || m.test.includes(f)))
    : MUTATIONS;
  const selected = selectMutations(filtered, {
    ...(changedFrom ? await changesSince(changedFrom) : {}),
    shard: shardArg ? parseShard(shardArg) : null,
  });

  if (selected.length === 0) {
    if (changedFrom || shardArg) {
      console.log(
        `\n[mutate-check] nothing to check here${changedFrom ? ` (no mutation target or test changed since ${changedFrom})` : ""}; the full run on main and nightly checks all ${MUTATIONS.length}.\n`,
      );
      process.exit(0);
    }
    console.error(`No mutation matches ${filters.join(", ")}`);
    process.exit(2);
  }

  /**
   * Refuse to run against uncommitted changes in any file we are about to break.
   * The in-memory restore below is the primary safety net; this is the one that
   * survives the process being killed mid-run, because `git checkout --` can then
   * put things back.
   */
  async function assertClean(files) {
    const { stdout } = await execFileP("git", ["status", "--porcelain", "--", ...files], {
      cwd: ROOT,
    });
    if (stdout.trim() !== "") {
      console.error("Refusing to run: uncommitted changes in files this would mutate.\n");
      console.error(stdout);
      console.error("Commit or stash first — a crash mid-run would lose them.");
      process.exit(2);
    }
  }

  const HAS_HEAVY = spawnSync("sh", ["-c", "command -v heavy"], { stdio: "ignore" }).status === 0;

  function runVitest(testFile) {
    return new Promise((resolve) => {
      // Each run takes its turn on the box (heavy), directly in CI.
      const [cmd, args] = vitestCommand(testFile, HAS_HEAVY);
      const child = spawn(cmd, args, { cwd: ROOT, stdio: ["ignore", "pipe", "pipe"] });
      let out = "";
      child.stdout.on("data", (d) => (out += d));
      child.stderr.on("data", (d) => (out += d));
      child.on("close", (code) => resolve({ code, out }));
    });
  }

  const targets = [...new Set(selected.map((m) => m.file))];
  await assertClean(targets);

  /** Every file we have touched, so a signal can put them all back. */
  const originals = new Map();

  async function restoreAll() {
    for (const [file, text] of originals) {
      await writeFile(path.join(ROOT, file), text, "utf8");
    }
    originals.clear();
  }

  for (const sig of ["SIGINT", "SIGTERM"]) {
    process.on(sig, async () => {
      await restoreAll();
      console.error(`\n[mutate-check] interrupted — restored ${targets.length} file(s)`);
      process.exit(130);
    });
  }

  const results = [];

  console.log(`\n[mutate-check] ${selected.length} mutation(s)\n`);

  for (const m of selected) {
    // Some tests need a real database. Without one they skip — and a skipped
    // test observes nothing, so the mutation would "survive" for the wrong
    // reason. Say so plainly instead; in CI, where the database is provided,
    // a missing one is a failure rather than a skip.
    if (m.needs && !process.env[m.needs]) {
      const verdict = process.env.CI ? "NO-ENV" : "skipped";
      results.push({ ...m, verdict, detail: `${m.needs} is not set` });
      console.log(`  ${verdict === "skipped" ? "skip  " : "NO-ENV"} ${m.id.padEnd(24)} needs ${m.needs}`);
      continue;
    }
    const abs = path.join(ROOT, m.file);
    const original = await readFile(abs, "utf8");
    const hits = original.split(m.find).length - 1;

    if (hits !== 1) {
      results.push({ ...m, verdict: "STALE", detail: `found ${hits}x, expected exactly 1` });
      console.log(`  STALE  ${m.id.padEnd(24)} anchor found ${hits}x in ${m.file}`);
      continue;
    }

    originals.set(m.file, original);
    try {
      await writeFile(abs, original.replace(m.find, m.replace), "utf8");
      const { code, out } = await runVitest(m.test);
      const verdict = judgeRun(code, out);
      results.push({ ...m, verdict });
      console.log(`  ${verdict.padEnd(6)} ${m.id.padEnd(24)} ${m.test}`);
      if (verdict === "NO-RUN") console.log(`         exit 0 without a vitest summary; output:\n${out.slice(-400)}`);
    } finally {
      await writeFile(abs, original, "utf8");
      originals.delete(m.file);
    }
  }

  const skipped = results.filter((r) => r.verdict === "skipped");
  const survivors = results.filter((r) => r.verdict !== "red" && r.verdict !== "skipped");
  if (skipped.length) {
    console.log(
      `\n[mutate-check] ${skipped.length} mutation(s) NOT CHECKED — their tests need a database.` +
        `\n  On the VPS: set -a; . /root/.high-desert-test.env; set +a  (CI always runs them)`,
    );
  }

  /** The verdicts as JSON, written whole (temp + rename) so a reader never sees half. */
  async function report(exit) {
    if (!jsonOut) return;
    const doc = {
      startedAt,
      finishedAt: new Date().toISOString(),
      exit,
      total: results.length,
      red: results.filter((r) => r.verdict === "red").length,
      skipped: skipped.map((r) => r.id),
      survived: survivors.map((r) => ({ id: r.id, verdict: r.verdict, test: r.test, file: r.file, why: r.why })),
    };
    const tmp = `${jsonOut}.tmp`;
    await writeFile(tmp, JSON.stringify(doc, null, 2) + "\n", "utf8");
    await rename(tmp, jsonOut);
  }

  console.log("");
  if (survivors.length === 0) {
    await report(0);
    console.log(
      `[mutate-check] all ${results.length - skipped.length} checked mutations went red. Every test observes its subject.\n`,
    );
    process.exit(0);
  }

  console.log("═".repeat(72));
  console.log(`  ${survivors.length} MUTATION(S) SURVIVED — these tests cannot see their subject`);
  console.log("═".repeat(72));
  for (const s of survivors) {
    console.log(`\n  ${s.id}  [${s.verdict}]`);
    console.log(`    test      ${s.test}`);
    console.log(`    mutated   ${s.file}`);
    console.log(`      -       ${s.find}`);
    console.log(`      +       ${s.replace}`);
    console.log(`    guards    ${s.why}`);
    if (s.detail) console.log(`    note      ${s.detail}`);
  }
  console.log("");
  await report(1);
  process.exit(1);
}
